write('DECOMPOSITION.json', {'idea': 'Turn existing external source mentions into measurement facets for decisions.', 'mechanism': 'Observation is a typed tuple, not a scalar or a verdict.', 'equations': ['o=(source_hash, locator, quantity, value, unit, statistic, population, protocol, region, time)', 'accept(o)=source_numeric_match AND unit_match AND protocol_match AND resolution_supported', 'target_transfer(o,e)=quantity_match AND observation_operator_match AND protocol_match; else UNKNOWN', 'group_mean=sum(y_i)/n is not an individual response or uncertainty bound'], 'operation': 'Extract -> freeze candidates -> verify against primary -> scope -> range intake -> draft edge proposal.', 'representation': 'Observation records with report lineage and exact primary source snapshots; no generated graph mutation.', 'leaves': [{'name': 'Source printed numbers', 'status': 'EXTERNALLY_MEASURED', 'stop': 'Primary observational record is the external boundary; apparatus errors not reconstructed without data.'}, {'name': 'Decimal comparison and unit conversion', 'status': 'DERIVED_UNDER_ASSUMPTIONS', 'stop': 'Exact decimal arithmetic given printed numbers; measurement uncertainty distinct.'}, {'name': 'Protocol-to-target transfer', 'status': 'UNKNOWN', 'stop': 'Matching names do not establish mechanics; require target-specific observation/calibration.'}, {'name': 'plausible_range', 'status': 'CONSTITUTIVE_CLOSURE', 'stop': 'Only inherited source-scoped intervals or mathematical domain; no universal empirical interval invented.'}, {'name': 'Decision useful ranking', 'status': 'CONSTITUTIVE_CLOSURE', 'stop': 'Transparent heuristic for inspection order, no optimal discovery claim.'}], 'rigorous_enclosure': 'No new affine physical sensitivity claimed. Exact arithmetic covers only finite printed observations.'})
